1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	import java.util.Map;
15	
16	/**
17	 * Maps Owner & OwnerDto using Mapstruct
18	 */
19	@Mapper(uses = PetMapper.class)
20	public interface OwnerMapper {
21	
22	    @Mapping(target = "displayName", expression = "java(displayName(owner))")
23	    @Mapping(target = "initials", expression = "java(initials(owner))")
24	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneDisplay(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
28	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
29	    @Mapping(target = "bulkSignupWarning", ignore = true)
30	    OwnerDto toOwnerDto(Owner owner);
31	
32	    /**
33	     * The owner's age band, derived at read time from {@code birthDate} relative to the
34	     * {@code registrationDate}: {@code MINOR} under 18, {@code ADULT} from 18 to 64 and
35	     * {@code SENIOR} at 65 or older. Null when the owner or its {@code birthDate} (or the
36	     * {@code registrationDate} it is measured against) is absent, so the field is simply
37	     * omitted for owners without a birth date.
38	     */
39	    default String ageBand(Owner owner) {
40	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
41	            return null;
42	        }
43	        int years = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
44	        if (years < 18) {
45	            return "MINOR";
46	        }
47	        if (years < 65) {
48	            return "ADULT";
49	        }
50	        return "SENIOR";
51	    }
52	
53	    /**
54	     * A single Luhn check digit (0-9) computed at read time over the digits contained in the
55	     * owner's customerCode. Non-digit characters (the hyphen and letters in '<REGION>-<HASH8>')
56	     * are skipped. Null when the owner or its customerCode is absent.
57	     */
58	    default Integer checkDigit(Owner owner) {
59	        if (owner == null || owner.getCustomerCode() == null) {
60	            return null;
61	        }
62	        String code = owner.getCustomerCode();
63	        int sum = 0;
64	        boolean dbl = true;
65	        for (int i = code.length() - 1; i >= 0; i--) {
66	            char c = code.charAt(i);
67	            if (c < '0' || c > '9') {
68	                continue;
69	            }
70	            int d = c - '0';
71	            if (dbl) {
72	                d *= 2;
73	                if (d > 9) {
74	                    d -= 9;
75	                }
76	            }
77	            sum += d;
78	            dbl = !dbl;
79	        }
80	        return (10 - (sum % 10)) % 10;
81	    }
82	
83	    /**
84	     * The owner's preferred contact channel, derived at read time: {@code EMAIL}
85	     * when an email address is present, otherwise {@code PHONE}.
86	     */
87	    default String contactPreference(Owner owner) {
88	        if (owner == null) {
89	            return null;
90	        }
91	        String email = owner.getEmail();
92	        return (email != null && !email.isBlank()) ? "EMAIL" : "PHONE";
93	    }
94	
95	    /** Fixed city-to-region table used to derive an owner's locality at read time. */
96	    Map<String, String> CITY_REGION = Map.of(
97	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
98	
99	    /** Region to its inclusive 4-digit postcode range {low, high}. */
100	    Map<String, int[]> REGION_POSTCODES = Map.of(
101	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
102	
103	    /**
104	     * The owner's locality, derived at read time from the region-and-hash identity: the REGION
105	     * prefix of the {@code customerCode} (everything before the first hyphen). That region was
106	     * itself derived at write time from the postcode (preferred) or city, defaulting to
107	     * {@code UNKNOWN}, so reading it back keeps locality and the identity in lock-step.
108	     *
109	     * <p>Owners predating the region-and-hash identity (e.g. seed data with no customerCode) fall
110	     * back to the historical read-time derivation: postcode preferred, then city, then
111	     * {@code UNKNOWN}.
112	     */
113	    default String locality(Owner owner) {
114	        if (owner == null) {
115	            return null;
116	        }
117	        String code = owner.getCustomerCode();
118	        if (code != null) {
119	            int dash = code.indexOf('-');
120	            return dash > 0 ? code.substring(0, dash) : code;
121	        }
122	        String byPostcode = regionFromPostcode(owner.getPostcode());
123	        if (byPostcode != null) {
124	            return byPostcode;
125	        }
126	        return CITY_REGION.getOrDefault(owner.getCity(), "UNKNOWN");
127	    }
128	
129	    /**
130	     * The region whose postcode range contains {@code postcode}, or {@code null} when the postcode is
131	     * absent, not four digits, or in no known range. Kept {@code private static} so MapStruct does not
132	     * treat it as a {@code String}-to-{@code String} property mapping method.
133	     */
134	    private static String regionFromPostcode(String postcode) {
135	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
136	            return null;
137	        }
138	        int value = Integer.parseInt(postcode);
139	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
140	            int[] range = entry.getValue();
141	            if (value >= range[0] && value <= range[1]) {
142	                return entry.getKey();
143	            }
144	        }
145	        return null;
146	    }
147	
148	    /** Known E.164 country codes, longest first so '61' matches before the shorter '1', mirroring
149	     *  the write-time normalization in NormalizeOwnerTelephone. */
150	    List<String> COUNTRY_CODES = List.of("61", "1");
151	
152	    /**
153	     * The stored E.164 {@code telephone} formatted for humans at read time: the country code, a single
154	     * space, then the national digits grouped in threes from the left, e.g. {@code '+61412345678'} ->
155	     * {@code '+61 412 345 678'}. The raw {@code telephone} is unchanged. Null when the owner is absent;
156	     * a value that is not a recognizable E.164 string (no leading {@code '+'}, non-digits, or no known
157	     * country code) is returned unchanged.
158	     */
159	    default String telephoneDisplay(Owner owner) {
160	        if (owner == null) {
161	            return null;
162	        }
163	        String telephone = owner.getTelephone();
164	        if (telephone == null || !telephone.startsWith("+")) {
165	            return telephone;
166	        }
167	        String digits = telephone.substring(1);
168	        if (!digits.matches("[0-9]+")) {
169	            return telephone;
170	        }
171	        String countryCode = null;
172	        for (String code : COUNTRY_CODES) {
173	            if (digits.startsWith(code)) {
174	                countryCode = code;
175	                break;
176	            }
177	        }
178	        if (countryCode == null) {
179	            return telephone;
180	        }
181	        String national = digits.substring(countryCode.length());
182	        StringBuilder grouped = new StringBuilder();
183	        for (int i = 0; i < national.length(); i++) {
184	            if (i > 0 && i % 3 == 0) {
185	                grouped.append(' ');
186	            }
187	            grouped.append(national.charAt(i));
188	        }
189	        return "+" + countryCode + (grouped.length() == 0 ? "" : " " + grouped);
190	    }
191	
192	    /** Formats the owner's stored names as 'LastName, FirstName'. */
193	    default String displayName(Owner owner) {
194	        if (owner == null) {
195	            return null;
196	        }
197	        return owner.getLastName() + ", " + owner.getFirstName();
198	    }
199	
200	    /**
201	     * The owner's initials as the upper-cased first letters of the first and last
202	     * names, dot-separated with a trailing dot, e.g. 'J.S.'.
203	     */
204	    default String initials(Owner owner) {
205	        if (owner == null) {
206	            return null;
207	        }
208	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
209	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
210	    }
211	
212	    Owner toOwner(OwnerDto ownerDto);
213	
214	    @Mapping(target = "id", ignore = true)
215	    @Mapping(target = "pets", ignore = true)
216	    @Mapping(target = "customerCode", ignore = true)
217	    @Mapping(target = "membershipNumber", ignore = true)
218	    @Mapping(target = "householdId", ignore = true)
219	    @Mapping(target = "namesakeCount", ignore = true)
220	    @Mapping(target = "householdSize", ignore = true)
221	    @Mapping(target = "membershipPoints", ignore = true)
222	    Owner toOwner(OwnerFieldsDto ownerDto);
223	
224	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
225	
226	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
227	
228	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
229	        OwnerPageDto ownerPageDto = new OwnerPageDto();
230	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
231	        ownerPageDto.setPage(ownerPage.getNumber());
232	        ownerPageDto.setSize(ownerPage.getSize());
233	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
234	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
235	        return ownerPageDto;
236	    }
237	}
