            if (dbl) {
                d *= 2;
                if (d > 9) {
                    d -= 9;
                }
            }
            sum += d;
            dbl = !dbl;
        }
        return (10 - (sum % 10)) % 10;
    }

    /**
     * The owner's preferred contact channel, derived at read time: {@code EMAIL}
     * when an email address is present, otherwise {@code PHONE}.
     */
    default String contactPreference(Owner owner) {
        if (owner == null) {
            return null;
